import React, { useState } from 'react';
import type { FilterLabel } from '../../types';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

const styles = `
@layer components {
  .chip-bar {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
    padding: var(--space-2) 0;
  }

  .chip {
    display: inline-flex;
    align-items: center;
    padding: var(--space-1) var(--space-3);
    border-radius: var(--radius-pill);
    border: 1px solid var(--color-border);
    background-color: var(--color-surface);
    color: var(--color-text-secondary);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-normal);
    line-height: var(--line-height-base);
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--easing-standard),
                color var(--duration-fast) var(--easing-standard),
                transform var(--duration-fast) var(--easing-standard);
  }

  .chip[aria-pressed="true"] {
    background-color: var(--color-accent);
    border-color: var(--color-accent);
    color: var(--color-accent-text);
    font-weight: var(--font-weight-medium);
  }

  .chip:hover:not([aria-pressed="true"]) {
    background-color: var(--color-surface-raised);
  }

  .chip:active {
    transform: scale(0.97);
  }
}
`;

export function ChipFilter(): React.ReactElement {
  const [activeFilter, setActiveFilter] = useState<FilterLabel>('All');

  return (
    <>
      <style>{styles}</style>
      <div className="chip-bar" role="group" aria-label="Filter chips">
        {FILTERS.map((label) => (
          <button
            key={label}
            type="button"
            className="chip"
            aria-pressed={activeFilter === label}
            onClick={() => setActiveFilter(label)}
          >
            {label}
          </button>
        ))}
      </div>
    </>
  );
}
